$want = @('context:colour-realism-ii-animals-alive-in-color','context:colour-realism-ii-cinematic-worlds','context:colour-realism-ii-color-you-can-almost-touch','context:colour-realism-ii-faces-under-extraordinary-light','context:colour-realism-ii-fire-neon-and-electric-color','context:colour-realism-ii-flowers-plants-and-natural-color','context:colour-realism-ii-materials-you-want-to-touch','context:colour-realism-ii-push-colour-realism','context:colour-realism-ii-reality-becomes-impossible','context:colour-realism-ii-water-glass-and-transparency')
$tmp = Join-Path $env:TEMP "aura-ctx-colour-realism.json"
ConvertTo-Json @($want) | Set-Content -Path $tmp -Encoding utf8
$out = (npx wrangler kv bulk get $tmp --namespace-id $ns --remote 2>$null | Out-String)
$hits = [regex]::Matches($out, '"(context:[^"]+)":\s*"((?:[^"\\]|\\.)*)"')
if ($hits.Count -eq 0) { "  none found" } else { foreach ($h in $hits) { "  removed " + $h.Groups[1].Value + ": " + $h.Groups[2].Value; npx wrangler kv key delete --namespace-id $ns $h.Groups[1].Value --remote 2>$null | Out-Null }; "  waiting 70 seconds"; Start-Sleep -Seconds 70 }
foreach ($c in $cats.Keys) { RUN ("REDO " + $final[$test[$c]]) }
